INSERT INTO changelog (title, body, created_at) VALUES ('Хронологія змійкою і попапи', 'Хронологія тепер — блоки по порядку, звʼязані лінією «змійкою» (на телефоні — вертикально). Клік по блоку — віконце з деталями: що робили і до чого дійшли. Де: Продукт → Паспорт і «Хронологія і план»; клієнт → Історія; Стратегія → Хроніка і хроніка частини.
Витяжка продукту тепер має розділ «Хронологія роботи» — Claude Code перелічує етапи по порядку з датами, і кожен етап стає блоком (дублікати пропускаються).
Довгий текст сховано у віконця: на екрані — коротко, клік — повністю (знання, рішення, ідеї в продуктах і стратегії; памʼять Джері по клієнту; матеріали; журнал змін реклами; висновки по рекламі; поля «Розвитку» — там же й правка). Закрити — ✕, Esc або клік повз.', datetime('now'));
